<#
.SYNOPSIS
  Find Windows certificate stores, signed programs and certificate files that still carry or chain to
  the eMudhra CA keys compromised in October 2026 (Mozilla Bug 2083449).

.DESCRIPTION
  Native PowerShell version of emudhra_scan.py for Windows machines without Python.
  Works in Windows PowerShell 5.1 and PowerShell 7+. Read-only; makes no network connections.

  CRITICAL  COMPROMISED_CA_CERT       a certificate for one of the 8 compromised CA keys
  CRITICAL  ISSUED_BY_COMPROMISED_CA  a certificate signed by one of those CAs (forgeable by anyone)
  WARNING   AFFECTED_ROOT             a root or CA that anchors or issued the compromised CAs
  INFO      the same, but in the Windows "Disallowed" store (protective)

  Exit code: 0 nothing found, 1 warnings only, 2 critical findings, 3 error.

.EXAMPLE
  powershell -ExecutionPolicy Bypass -File .\Scan-EmudhraRevoked.ps1
.EXAMPLE
  .\Scan-EmudhraRevoked.ps1 -Quick
.EXAMPLE
  .\Scan-EmudhraRevoked.ps1 -Path 'D:\Software' -JsonOut report.json
#>
[CmdletBinding()]
param(
    [switch]$Quick,
    [switch]$Full,
    [string[]]$Path,
    [switch]$NoTrustStores,
    [string]$JsonOut,
    [int]$MaxSizeMB = 256,
    [switch]$NoProcesses,
    [switch]$IncludeSelf,
    [switch]$SelfTest,
    [switch]$Quiet
)

Set-StrictMode -Version 2.0
$ErrorActionPreference = 'Continue'
$Version = '1.0.0'

