foreach ($e in $Ind.affected_roots) { $RootByPub[$e.public_key_hex] = $e; [void]$Markers.Add($e.name) }

$Advice = @{
    'COMPROMISED_CA_CERT'      = 'Certificate for a CA whose private key is public. Remove it from the trust store or bundle, or update the software that ships it.'
    'ISSUED_BY_COMPROMISED_CA' = 'Signed by a CA whose private key is public, so anyone could have forged it. Do not trust it; treat a program signed with it as untrusted.'
    'AFFECTED_ROOT'            = 'Root or CA that anchors or issued the compromised CAs (Mozilla and Chrome removed emSign ECC Root CA - G3). Without revocation checking, certificates minted with the compromised keys chain to it. Update the software or remove the certificate.'
}

# ---- certificate helpers ---------------------------------------------------------------------------
function Read-Tlv([byte[]]$buf, [int]$i, [int]$end) {
    if ($i + 2 -gt $end) { return $null }
    $tag = $buf[$i]; $b = $buf[$i + 1]
    if ($b -lt 0x80) { $len = $b; $j = $i + 2 }
    else {
        $n = $b -band 0x7f
        if ($n -eq 0 -or $n -gt 4 -or ($i + 2 + $n) -gt $end) { return $null }
        $len = 0; for ($k = 0; $k -lt $n; $k++) { $len = ($len * 256) + $buf[$i + 2 + $k] }
        $j = $i + 2 + $n
    }
    if ($j + $len -gt $end) { return $null }
    return @($tag, $j, ($j + $len))
}

function Get-AkiHex($cert) {
    foreach ($x in $cert.Extensions) {
        if ($x.Oid.Value -ne '2.5.29.35') { continue }
        $r = [byte[]]$x.RawData
        $t = Read-Tlv $r 0 $r.Length
        if ($null -eq $t -or $t[0] -ne 0x30) { return $null }
        $i = $t[1]
        while ($i -lt $t[2]) {
            $k = Read-Tlv $r $i $t[2]
            if ($null -eq $k) { return $null }
            if ($k[0] -eq 0x80) { $id = New-Object byte[] ($k[2] - $k[1]); [Array]::Copy($r, $k[1], $id, 0, $id.Length); return (ConvertTo-Hex $id) }
            $i = $k[2]
        }
    }
    return $null
}

function New-Cert([byte[]]$der) {
    try { return New-Object System.Security.Cryptography.X509Certificates.X509Certificate2 (, $der) } catch { return $null }
}

function Get-CN([string]$dn) {
    $m = [regex]::Match($dn, '(?:^|,\s*)CN=("([^"]*)"|[^,]*)')
    if ($m.Success) { if ($m.Groups[2].Success -and $m.Groups[2].Value) { return $m.Groups[2].Value }; return $m.Groups[1].Value.Trim() }
    return $dn
}

function Get-Classification($c) {
    try { $pub = ConvertTo-Hex $c.PublicKey.EncodedKeyValue.RawData } catch { $pub = '' }
    if ($CaByPub.ContainsKey($pub)) { return @('COMPROMISED_CA_CERT', $CaByPub[$pub]) }
    $iss = ConvertTo-Hex $c.IssuerName.RawData
    if ($CaByDn.ContainsKey($iss)) { return @('ISSUED_BY_COMPROMISED_CA', $CaByDn[$iss]) }
    $aki = Get-AkiHex $c
    if ($aki -and $CaBySki.ContainsKey($aki)) { return @('ISSUED_BY_COMPROMISED_CA', $CaBySki[$aki]) }
    if ($RootByPub.ContainsKey($pub)) { return @('AFFECTED_ROOT', $RootByPub[$pub]) }
    return $null
}

function Get-B64Bytes([string]$body) {
    $clean = [regex]::Replace($body, '\\[rn]', '')
    $clean = [regex]::Replace($clean, '[^A-Za-z0-9+/=]', '')
    $pad = (4 - ($clean.Length % 4)) % 4
    $clean = $clean + ('=' * $pad)
    try { return , ([Convert]::FromBase64String($clean)) } catch { return $null }
}

# Returns a list of @{Cert; How} for every certificate inside $bytes.
function Find-Certs([byte[]]$bytes, [int]$depth = 0) {
    $out = New-Object System.Collections.ArrayList
    if ($null -eq $bytes -or $bytes.Length -lt 64) { return , $out }
    $s = $Latin1.GetString($bytes)
    $hit = $false
    foreach ($m in $Markers) { if ($s.IndexOf($m, [StringComparison]::Ordinal) -ge 0) { $hit = $true; break } }
    if ($hit) {
        foreach ($m in [regex]::Matches($s, '\x30\x82[\s\S]{2}\x30\x82')) {
            $i = $m.Index; $len = ($bytes[$i + 2] * 256) + $bytes[$i + 3] + 4
            if ($i + $len -gt $bytes.Length) { continue }
            $slice = New-Object byte[] $len; [Array]::Copy($bytes, $i, $slice, 0, $len)
            $c = New-Cert $slice
            if ($c) { [void]$out.Add(@{ Cert = $c; How = 'der' }) }
        }
    }
    if ($depth -gt 2) { return , $out }
    if ($s.IndexOf('-----BEGIN ', [StringComparison]::Ordinal) -ge 0) {
        foreach ($m in [regex]::Matches($s, '-----BEGIN (X509 CERTIFICATE|TRUSTED CERTIFICATE|CERTIFICATE|PKCS7|CMS)-----([\s\S]{20,200000}?)-----END ')) {
            $raw = Get-B64Bytes $m.Groups[2].Value
            if ($null -eq $raw -or $raw.Length -eq 0) { continue }
            $kind = $m.Groups[1].Value
            if ($kind -eq 'PKCS7' -or $kind -eq 'CMS') {
                foreach ($x in (Find-Certs $raw ($depth + 1))) { $x.How = 'pem-pkcs7'; [void]$out.Add($x) }
                continue
            }
            if ($kind -eq 'TRUSTED CERTIFICATE') {
                $t = Read-Tlv $raw 0 $raw.Length
                if ($null -eq $t) { continue }
                $tmp = New-Object byte[] $t[2]; [Array]::Copy($raw, 0, $tmp, 0, $t[2]); $raw = $tmp
            }
            $c = New-Cert $raw
            if ($c) { [void]$out.Add(@{ Cert = $c; How = 'pem' }) }
        }
    }
    if ($s.IndexOf('# SIG # Begin signature block', [StringComparison]::Ordinal) -ge 0) {
        foreach ($m in [regex]::Matches($s, '# SIG # Begin signature block([\s\S]{20,400000}?)# SIG # End signature block')) {
            $body = [regex]::Replace($m.Groups[1].Value, '(?m)^#\s?', '')
            $raw = Get-B64Bytes $body
            if ($raw) { foreach ($x in (Find-Certs $raw ($depth + 1))) { $x.How = 'powershell-signature'; [void]$out.Add($x) } }
        }
    }
    return , $out
}

# ---- findings --------------------------------------------------------------------------------------
$Findings = New-Object System.Collections.ArrayList
$Seen = @{}
$Stats = [ordered]@{ trust_store_sources = 0; files_scanned = 0; files_skipped_size = 0; files_unreadable = 0; bytes_scanned = 0; certificates_parsed = 0 }

function Add-Finding($c, [string]$location, [string]$source, [string]$container, [string]$how, [string]$store) {
    $Stats.certificates_parsed++
    $cls = Get-Classification $c
    if ($null -eq $cls) { return }
    $kind = $cls[0]; $e = $cls[1]
    $sha = ConvertTo-Hex ($Sha256.ComputeHash($c.RawData))
    $key = "$location|$container|$sha|$kind"
    if ($Seen.ContainsKey($key)) { return }
    $Seen[$key] = $true
    $sev = 'CRITICAL'; if ($kind -eq 'AFFECTED_ROOT') { $sev = 'WARNING' }
    $advice = $Advice[$kind]
    if ($store -and ($store -eq 'Disallowed' -or $store -eq 'Untrusted')) { $sev = 'INFO'; $advice = "Found in the '$store' store, which blocks it. This is protective." }
    [void]$Findings.Add([ordered]@{
            severity = $sev; kind = $kind; indicator = $e.name; source = $source; location = $location; container = $container
            found_as = $how; store = $store; advice = $advice; running_processes = @(); signature_status = $null
            certificate = [ordered]@{ subject_cn = (Get-CN $c.Subject); issuer_cn = (Get-CN $c.Issuer); serial = $c.SerialNumber.ToLowerInvariant()
                not_before = $c.NotBefore.ToUniversalTime().ToString('s') + 'Z'; not_after = $c.NotAfter.ToUniversalTime().ToString('s') + 'Z'; sha256 = $sha }
        })
}

function Test-Bytes([byte[]]$bytes, [string]$location, [string]$source, [string]$container, [string]$store) {
    foreach ($x in (Find-Certs $bytes)) { Add-Finding $x.Cert $location $source $container $x.How $store }
}

# ---- files -----------------------------------------------------------------------------------------
$SignedExts = '.exe .dll .sys .ocx .cpl .scr .efi .mui .drv .com .msi .msp .msm .cab .cat .ps1 .psm1 .psd1 .ps1xml .psc1 .vbs .wsf .appx .msix .appxbundle .msixbundle .jar .war .ear .apk .aab .xpi .vsix .nupkg .so .dylib .node .bundle .pkg .winmd .xll .sst .stl .p7x .asar'.Split(' ')
$CertExts = '.pem .crt .cer .der .cert .p7b .p7c .p7s .spc .pfx .p12 .jks .keystore .truststore .bks .ks .ca-bundle .chain'.Split(' ')
$TextExts = '.conf .cfg .cnf .config .yaml .yml .json .xml .properties .toml .ini .env'.Split(' ')
$ZipExts = '.jar .war .ear .apk .aab .xpi .vsix .nupkg .appx .msix .appxbundle .msixbundle .zip .whl .ipa'.Split(' ')
$NameHints = 'cacerts ca-bundle ca-certificates cert.pem cert8.db cert9.db libnssckbi nssckbi roots.pem tls-ca-bundle authroot trustedcerts'.Split(' ')
$SkipDirNames = @('.git', '.hg', '.svn', '__pycache__', '$Recycle.Bin', 'System Volume Information', 'WinSxS')
$MaxBytes = [int64]$MaxSizeMB * 1MB
$ScriptDir = Split-Path -Parent $PSCommandPath
$OwnPaths = @($PSCommandPath, (Join-Path $ScriptDir 'indicators'), (Join-Path $ScriptDir 'tests'), (Join-Path $ScriptDir 'emudhra_scan.py'))
$Visited = @{}
$LastProgress = [DateTime]::UtcNow

function Test-Wanted([System.IO.FileInfo]$fi, [bool]$force) {
    if ($fi.Length -eq 0) { return $false }
    if ($fi.Length -gt $MaxBytes) { $Stats.files_skipped_size++; return $false }
    if ($force) { return $true }
    $name = $fi.Name.ToLowerInvariant(); $ext = $fi.Extension.ToLowerInvariant()
    if ($SignedExts -contains $ext -or $CertExts -contains $ext) { return $true }
    foreach ($h in $NameHints) { if ($name.StartsWith($h)) { return $true } }
    if ($TextExts -contains $ext) { return ($fi.Length -le 2MB) }
    if ($ext -eq '' -or $name -match '\.so(\.\d+)*$') {
        try {
            $fs = [System.IO.File]::OpenRead($fi.FullName); $head = New-Object byte[] 4; [void]$fs.Read($head, 0, 4); $fs.Close()
            $h = ConvertTo-Hex $head
            return ($h.StartsWith('4d5a') -or $h -eq '7f454c46' -or $h -in @('feedface', 'feedfacf', 'cefaedfe', 'cffaedfe', 'cafebabe', '504b0304', 'd0cf11e0', '4d534346'))
        } catch { return $false }
    }
    return $false
}

function Test-Zip([object]$zipSource, [string]$location, [string]$source, [int]$depth, [string]$prefix) {
    try {
        if ($zipSource -is [string]) { $za = [System.IO.Compression.ZipFile]::OpenRead($zipSource) }
        else { $za = New-Object System.IO.Compression.ZipArchive ($zipSource, [System.IO.Compression.ZipArchiveMode]::Read) }
    } catch { return }
    try {
        foreach ($en in $za.Entries) {
            if ($en.Length -eq 0 -or $en.Length -gt $MaxBytes) { continue }
            $n = $en.FullName.ToLowerInvariant(); $ext = [System.IO.Path]::GetExtension($n)
            $leaf = [System.IO.Path]::GetFileName($n)
            $interesting = ($n.StartsWith('meta-inf/') -and (@('.rsa', '.dsa', '.ec', '.p7s', '.p7b') -contains $ext)) -or ($CertExts -contains $ext) -or `
            (@('.p7x', '.cat', '.exe', '.dll', '.sys', '.ps1', '.msi', '.so', '.dylib', '.node') -contains $ext)
            foreach ($h in $NameHints) { if ($leaf.StartsWith($h)) { $interesting = $true } }
            $nested = ($ZipExts -contains $ext) -and $depth -lt 2 -and $en.Length -le 256MB
            if (-not ($interesting -or $nested)) { continue }
            $ms = New-Object System.IO.MemoryStream
            $st = $en.Open(); $st.CopyTo($ms); $st.Close()
            $data = $ms.ToArray()
            if ($interesting) { Test-Bytes $data $location $source ($prefix + $en.FullName) $null }
            if ($nested -and $data.Length -gt 4 -and $data[0] -eq 0x50 -and $data[1] -eq 0x4b) {
                Test-Zip (New-Object System.IO.MemoryStream (, $data)) $location $source ($depth + 1) ($prefix + $en.FullName + '!/')
            }
        }
    } catch { } finally { $za.Dispose() }
}

function Test-File([string]$p, [string]$source, [bool]$force) {
    try { $fi = New-Object System.IO.FileInfo $p } catch { $Stats.files_unreadable++; return }
    if (-not $fi.Exists) { return }
    $full = $fi.FullName
    if ($Visited.ContainsKey($full)) { return }
    if (-not $IncludeSelf) { foreach ($o in $OwnPaths) { if ($o -and ($full -eq $o -or $full.StartsWith($o + [System.IO.Path]::DirectorySeparatorChar))) { return } } }
    if (-not (Test-Wanted $fi $force)) { return }
    $Visited[$full] = $true
    try { $bytes = [System.IO.File]::ReadAllBytes($full) } catch { $Stats.files_unreadable++; return }
    Test-Bytes $bytes $full $source $null $null
    if ($bytes.Length -gt 4 -and $bytes[0] -eq 0x50 -and $bytes[1] -eq 0x4b -and ($ZipExts -contains $fi.Extension.ToLowerInvariant())) {
        Test-Zip $full $full $source 0 ''
    }
    $Stats.files_scanned++; $Stats.bytes_scanned += $fi.Length
    if (-not $Quiet -and ([DateTime]::UtcNow - $script:LastProgress).TotalSeconds -gt 5) {
        $script:LastProgress = [DateTime]::UtcNow
        [Console]::Error.WriteLine(("  ... {0} files scanned, {1} findings" -f $Stats.files_scanned, $Findings.Count))
    }
}

function Invoke-Walk([string[]]$roots, [string]$source) {
    foreach ($r in $roots) {
        if (-not $r -or -not (Test-Path -LiteralPath $r)) { continue }
        if (Test-Path -LiteralPath $r -PathType Leaf) { Test-File $r $source $true; continue }
        $stack = New-Object System.Collections.Stack
        $stack.Push((Resolve-Path -LiteralPath $r).ProviderPath)
        while ($stack.Count -gt 0) {
            $d = $stack.Pop()
            try { $files = [System.IO.Directory]::GetFiles($d) } catch { $files = @() }
            foreach ($f in $files) { Test-File $f $source $false }
            try { $dirs = [System.IO.Directory]::GetDirectories($d) } catch { $dirs = @() }
            foreach ($sub in $dirs) {
                $leaf = [System.IO.Path]::GetFileName($sub)
                if ($SkipDirNames -contains $leaf) { continue }
                try { if (([System.IO.File]::GetAttributes($sub) -band [System.IO.FileAttributes]::ReparsePoint) -ne 0) { continue } } catch { continue }
                $stack.Push($sub)
            }
        }
    }
}

# ---- trust stores ----------------------------------------------------------------------------------
function Invoke-TrustStores {
    if ($OnWindows) {
        foreach ($loc in @('LocalMachine', 'CurrentUser')) {
            foreach ($st in (Get-ChildItem -Path "Cert:\$loc" -ErrorAction SilentlyContinue)) {
                $Stats.trust_store_sources++
                foreach ($c in (Get-ChildItem -Path "Cert:\$loc\$($st.Name)" -ErrorAction SilentlyContinue)) {
                    if ($c -is [System.Security.Cryptography.X509Certificates.X509Certificate2]) {
                        Add-Finding $c "Windows certificate store: $loc\$($st.Name)" 'trust-store' $null 'os-store' $st.Name
                    }
                }
            }
        }
    }
    $files = New-Object System.Collections.ArrayList
    foreach ($v in @('SSL_CERT_FILE', 'REQUESTS_CA_BUNDLE', 'CURL_CA_BUNDLE', 'NODE_EXTRA_CA_CERTS', 'GIT_SSL_CAINFO')) {
        $x = [Environment]::GetEnvironmentVariable($v); if ($x) { [void]$files.Add($x) }
    }
    if ($env:JAVA_HOME) { [void]$files.Add((Join-Path $env:JAVA_HOME 'lib\security\cacerts')); [void]$files.Add((Join-Path $env:JAVA_HOME 'jre\lib\security\cacerts')) }
    foreach ($pf in @($env:ProgramFiles, ${env:ProgramFiles(x86)})) {
        if ($pf) {
            [void]$files.Add((Join-Path $pf 'Mozilla Firefox\nssckbi.dll'))
            [void]$files.Add((Join-Path $pf 'Git\mingw64\etc\ssl\certs\ca-bundle.crt'))
            [void]$files.Add((Join-Path $pf 'Git\mingw64\ssl\certs\ca-bundle.crt'))
        }
    }
    if ($env:APPDATA) {
        $prof = Join-Path $env:APPDATA 'Mozilla\Firefox\Profiles'
        if (Test-Path -LiteralPath $prof) { foreach ($d in (Get-ChildItem -LiteralPath $prof -Directory -ErrorAction SilentlyContinue)) { [void]$files.Add((Join-Path $d.FullName 'cert9.db')) } }
    }
    if (-not $OnWindows) { foreach ($x in @('/etc/ssl/certs/ca-certificates.crt', '/etc/pki/tls/certs/ca-bundle.crt', '/etc/ssl/cert.pem')) { [void]$files.Add($x) } }
    foreach ($f in $files) { if (Test-Path -LiteralPath $f -PathType Leaf) { $Stats.trust_store_sources++; Test-File $f 'trust-store' $true } }
}

function Get-DefaultRoots {
    if (-not $OnWindows) { return @('/usr', '/opt', '/etc') }
    if ($Full) { return @(Get-PSDrive -PSProvider FileSystem | Where-Object { $_.Free -ne $null } | ForEach-Object { $_.Root }) }
    $sysroot = $env:SystemRoot; if (-not $sysroot) { $sysroot = 'C:\Windows' }
    return @($env:ProgramFiles, ${env:ProgramFiles(x86)}, $env:ProgramW6432, $env:ProgramData, $env:LOCALAPPDATA, $env:APPDATA, (Join-Path $sysroot 'System32\drivers')) |
    Where-Object { $_ } | Select-Object -Unique
}

# ---- self-test -------------------------------------------------------------------------------------
function Invoke-SelfTest {
    $m = [regex]::Match($SelfTestPem, '-----BEGIN CERTIFICATE-----([\s\S]+?)-----END')
    $der = Get-B64Bytes $m.Groups[1].Value
    $c = New-Cert $der
    $cls = $null; if ($null -ne $c) { $cls = Get-Classification $c }
    $r1 = ($null -ne $cls) -and ($cls[0] -eq 'COMPROMISED_CA_CERT')
    $rnd = New-Object byte[] 4096; (New-Object Random).NextBytes($rnd)
    $blob = New-Object System.Collections.Generic.List[byte]; $blob.AddRange($rnd); $blob.AddRange($der); $blob.AddRange($rnd)
    $r2 = @((Find-Certs $blob.ToArray()) | Where-Object { Get-Classification $_.Cert }).Count -gt 0
    $js = '{"ca": "' + $SelfTestPem.Trim().Replace("`r", '').Replace("`n", '\n') + '"}'
    $r3 = @((Find-Certs $Latin1.GetBytes($js)) | Where-Object { Get-Classification $_.Cert }).Count -gt 0
    "{0,-22} {1}" -f 'parse_and_match', $(if ($r1) { 'ok' } else { 'FAILED' })
    "{0,-22} {1}" -f 'raw_der_in_binary', $(if ($r2) { 'ok' } else { 'FAILED' })
    "{0,-22} {1}" -f 'escaped_pem_in_json', $(if ($r3) { 'ok' } else { 'FAILED' })
    $ok = $r1 -and $r2 -and $r3
    "self-test " + $(if ($ok) { 'passed' } else { 'FAILED' })
    return $ok
}

# ---- main ------------------------------------------------------------------------------------------
if ($SelfTest) {
    $res = Invoke-SelfTest
    $res | Where-Object { $_ -is [string] } | ForEach-Object { Write-Output $_ }
    if ($res[-1] -eq $true) { exit 0 } else { exit 3 }
}

try { Add-Type -AssemblyName System.IO.Compression.FileSystem -ErrorAction Stop } catch { }
$t0 = [DateTime]::UtcNow
if (-not $NoTrustStores) {
    if (-not $Quiet) { [Console]::Error.WriteLine('Scanning trust stores and certificate bundles...') }
    Invoke-TrustStores
}
$mode = 'default'
if ($Quick) { $mode = 'quick' } elseif ($Path) { $mode = 'paths' } elseif ($Full) { $mode = 'full' }
if (-not $Quick) {
    $roots = $Path; if (-not $roots) { $roots = Get-DefaultRoots }
    if (-not $Quiet) { [Console]::Error.WriteLine('Scanning files under: ' + ($roots -join ', ')) }
    Invoke-Walk $roots 'file'
}

if ($Findings.Count -gt 0) {
    $procs = @{}
    if (-not $NoProcesses) {
        foreach ($p in (Get-Process -ErrorAction SilentlyContinue)) {
            try { $pp = $p.Path } catch { $pp = $null }
            if ($pp) { if (-not $procs.ContainsKey($pp)) { $procs[$pp] = New-Object System.Collections.ArrayList }; [void]$procs[$pp].Add($p.Id) }
        }
    }
    foreach ($f in $Findings) {
        if ($procs.ContainsKey($f.location)) { $f.running_processes = @($procs[$f.location]) }
        if ($OnWindows -and $f.source -eq 'file' -and (Test-Path -LiteralPath $f.location -PathType Leaf)) {
            try { $sig = Get-AuthenticodeSignature -LiteralPath $f.location -ErrorAction Stop; $f.signature_status = [string]$sig.Status } catch { }
        }
    }
}

$order = @{ CRITICAL = 0; WARNING = 1; INFO = 2 }
$sorted = @($Findings | Sort-Object @{ Expression = { $order[$_.severity] } }, @{ Expression = { $_.indicator } }, @{ Expression = { $_.location } })
$seconds = [math]::Round(([DateTime]::UtcNow - $t0).TotalSeconds, 1)
$hostDesc = if ($OnWindows) { [Environment]::OSVersion.VersionString } else { [System.Runtime.InteropServices.RuntimeInformation]::OSDescription }

Write-Output ("eMudhra compromised-CA scanner {0} (PowerShell)  (Mozilla Bug 2083449)" -f $Version)
Write-Output ("Host: {0}   PowerShell {1}   Mode: {2}" -f $hostDesc, $PSVersionTable.PSVersion, $mode)
Write-Output ("Scanned {0} trust-store sources and {1} files ({2:N1} MB) in {3} s; {4} certificates parsed." -f $Stats.trust_store_sources, $Stats.files_scanned, ($Stats.bytes_scanned / 1e6), $seconds, $Stats.certificates_parsed)
if ($Stats.files_skipped_size -or $Stats.files_unreadable) { Write-Output ("Skipped {0} files over the size limit and {1} unreadable files." -f $Stats.files_skipped_size, $Stats.files_unreadable) }
foreach ($sev in @('CRITICAL', 'WARNING', 'INFO')) {
    $g = @($sorted | Where-Object { $_.severity -eq $sev })
    if ($g.Count -eq 0) { continue }
    Write-Output ''
    Write-Output ("{0} ({1})" -f $sev, $g.Count)
    foreach ($f in $g) {
        $c = $f.certificate
        Write-Output ("  [{0}] {1}" -f $f.kind, $f.indicator)
        $where = $f.location; if ($f.container) { $where += "  (inside: $($f.container))" }
        Write-Output ("     where : {0}" -f $where)
        Write-Output ("     cert  : CN={0}  issued by CN={1}" -f $c.subject_cn, $c.issuer_cn)
        Write-Output ("             valid {0} to {1}  sha256 {2}" -f $c.not_before, $c.not_after, $c.sha256)
        if ($f.signature_status) { Write-Output ("     signature status (Windows): {0}" -f $f.signature_status) }
        if (@($f.running_processes).Count -gt 0) { Write-Output ("     running: PIDs {0}" -f (@($f.running_processes) -join ', ')) }
        Write-Output ("     action: {0}" -f $f.advice)
    }
}
$crit = @($sorted | Where-Object { $_.severity -eq 'CRITICAL' }).Count
$warn = @($sorted | Where-Object { $_.severity -eq 'WARNING' }).Count
Write-Output ''
if ($crit -or $warn) { Write-Output ("Result: {0} critical, {1} warning findings." -f $crit, $warn) }
else { Write-Output 'Result: no certificates for the compromised eMudhra CAs or their roots were found.' }

if ($JsonOut) {
    $doc = [ordered]@{ meta = [ordered]@{ tool = 'Scan-EmudhraRevoked.ps1'; version = $Version; host = $hostDesc; powershell = [string]$PSVersionTable.PSVersion; mode = $mode; seconds = $seconds; indicators_generated = $Ind.generated }
        stats = $Stats; findings = $sorted }
    $doc | ConvertTo-Json -Depth 8 | Set-Content -LiteralPath $JsonOut -Encoding UTF8
}
if ($crit) { exit 2 } elseif ($warn) { exit 1 } else { exit 0 }
